end
return o
end
local function _VM(prog)
local out={}
local acc=0
local i=1
local n=#prog
while i<=n do
local op=prog[i]
local arg=prog[i+1] or 0
i=i+2
if op==1 then out[#out+1]=arg
elseif op==3 then acc=_xor(acc,arg)
end
end
return out
end
local function _DEC(enc)
local o={}
for i=1,#enc do
local x=enc[i]
local idx=i-1
x=(x-_K[((idx*3)%32)+1])%256
x=_xor(x,_K[((idx+11)%32)+1])
x=(x-((idx*31)%256))%256
x=_xor(x,_K[(idx%32)+1])
o[i]=string.char(x)
end
return table.concat(o)
end
